#!/usr/bin/env python3
"""Compress or decompress a file using only Python's standard library."""
import lzma
import sys


def main():
    args = sys.argv[1:]
    if len(args) == 2:
        source, dest = args
        data = lzma.compress(open(source, 'rb').read(), preset=9)
    elif len(args) == 3 and args[0] == '--decompress':
        _, source, dest = args
        data = lzma.decompress(open(source, 'rb').read())
    else:
        raise SystemExit('usage: compress.py [--decompress] SOURCE DEST')
    with open(dest, 'wb') as f:
        f.write(data)


if __name__ == '__main__':
    main()

