def pack7(digits):
    # Thirty-two base-7 digits fit in 90 bits.
    out = bytearray()
    acc = bits = 0
    for i in range(0, len(digits), 32):
        block = digits[i:i+32]
        value = 0
        for d in block: value = value * 7 + d
        value *= 7 ** (32-len(block))
        acc = (acc << 90) | value
        bits += 90
        while bits >= 8:
            bits -= 8
            out.append((acc >> bits) & 255)
            acc &= (1 << bits) - 1
    if bits: out.append(acc << (8-bits))
    return bytes(out)


def unpack7(data):
    out = bytearray()
    acc = bits = 0
    for b in data:
        acc = (acc << 8) | b
        bits += 8
